s=s.replace("export async function deliverGenerated({ root, repo, base, token, branch: targetBranch = null, pr: targetPr = null, files, title, body, message, task = null, log = console.log }) {",
"export async function deliverGenerated({ root, repo, base, token, branch: targetBranch = null, pr: targetPr = null, files, moves = {}, title, body, message, task = null, log = console.log }) {")
s=s.replace("const commit = pushGenerated(root, { remote, baseSha, branch, files, message: withTaskTrailer(message, task) });",
"const commit = pushGenerated(root, { remote, baseSha, branch, files, moves, message: withTaskTrailer(message, task) });")
open(p,'w').write(s)
